// A mission's PRD as the store keeps it (PRD omni-loop-21 s3b): a repository PRD's number (`2896`) or a product PRD's id
// (`omni-loop-15`). The mission tables that name a PRD (supabase/migrations/20270129100000_mission_product_prd.sql) write a number
// to `prd` and a product's id to `product_prd`, never both, and read it back as `prd_id`, its text either way, generated by the
// database. A job's key names it the same way: `mission:<id>:prd:<number or id>:…`.
import { z } from 'zod';
import { isProductPrdId, PrdNumberSchema, ProductPrdIdSchema, type PrdNumber, type ProductPrdId } from 'omni-loop/kit/lib/ids.ts';

/** A PRD of a mission: a repository's, by its number, or a product's, by its id. */
export type MissionPrd = PrdNumber | ProductPrdId;

/** `prd_id` as the database gives it: a product PRD's id, or a repository PRD's number as text. */
export const PrdIdSchema: z.ZodType<MissionPrd, string> = z.union([
  ProductPrdIdSchema,
  z.string().regex(/^[1-9]\d{0,9}$/).transform(Number).pipe(PrdNumberSchema),
]);

/** The two columns a PRD is written to: its number to `prd`, a product's id to `product_prd`; both null for none. */
export function prdColumns(prd: MissionPrd | null): { prd: PrdNumber | null; product_prd: ProductPrdId | null } {
  if (prd === null) return { prd: null, product_prd: null };
  return isProductPrdId(prd) ? { prd: null, product_prd: prd } : { prd, product_prd: null };
}

/** The PRD a mission's job key names (`mission:<id>:prd:<n or id>:…`), or null when it names none or none that reads. */
export function prdOfKey(key: string): MissionPrd | null {
  const named = /^mission:[0-9a-f-]{36}:prd:([^:]+):/.exec(key)?.[1];
  if (named === undefined) return null;
  const prd = PrdIdSchema.safeParse(named);
  return prd.success ? prd.data : null;
}

/** The part of a job key that names its PRD: `prd:2896` or `prd:omni-loop-15`. */
export const prdKeyPart = (prd: MissionPrd): string => `prd:${String(prd)}`;

/** The product PRD and run a build's key names (`mission:<id>:prd:<key>-<n>:run:<k>`, PRD omni-loop-21 s9b); null for any other key. */
export function productRunOfKey(key: string): { prd: ProductPrdId; run: number } | null {
  const match = /^mission:[0-9a-f-]{36}:prd:([^:]+):run:([1-9][0-9]*)$/.exec(key);
  const prd = ProductPrdIdSchema.safeParse(match?.[1]);
  return match !== null && prd.success ? { prd: prd.data, run: Number(match[2]) } : null;
}

/** A product PRD's id, beside a `prd` left null, on a row read for a reader that knows a repository PRD's number only. */
export type ProductNamed = { product?: ProductPrdId };

/**
 * A PRD for a reader that knows a repository PRD's number only (the supervisor, until it takes products: PRD omni-loop-21 s7): a
 * number as `prd`; a product's id as `product`, with `prd` null.
 */
export function numberedOf(prd: MissionPrd | null): { prd: PrdNumber | null } & ProductNamed {
  return prd !== null && isProductPrdId(prd) ? { prd: null, product: prd } : { prd };
}
